<script lang="ts">import type{MessageActionAlign}from'@fex-design/core/message/types';import{messageActionsClassName}from'@fex-design/styles/message';import{cn}from'@fex/utils';import{getContext,type Snippet}from'svelte';import type{HTMLAttributes}from'svelte/elements';import{messageContextKey,type MessageContextValue}from'./context';interface Props extends HTMLAttributes<HTMLDivElement>{align?:MessageActionAlign;visibility?:'always'|'interaction';children?:Snippet}let{align:alignProp='inherit',visibility='always',class:className,children,...rest}:Props=$props();const context=getContext<MessageContextValue|undefined>(messageContextKey);let align=$derived(alignProp==='inherit'?(context?.side()??'start'):alignProp)</script><div {...rest} data-slot="message-actions" data-align={align} data-visibility={visibility} class={cn(messageActionsClassName,className)}>{@render children?.()}</div>
